import test from 'node:test';import assert from 'node:assert/strict';import records from '../../crates/geod-runtime/src/datasets/soilgrids-reviewed-index.json' with {type:'json'};import {nextDirectRange} from './next-public-products.js';
function source(record){const layer={id:record.layer,scale:1,offset:0,nodata:255,unit:record.layer==='most-probable'?'WRB class code':'raw score'},dataset={id:'soilgrids',title:'SoilGrids250m WRB 2017 corrected originals',version:records.release,layers:[layer]},proof={schemaVersion:2,dataset,layer,request:{datasetId:'soilgrids',layer:record.layer},sourceId:record.id,sourceBounds:record.bounds,declarationKind:'reviewed-client-preset; publisher file bytes and embedded metadata verified separately'};return{dataset,asset:{key:'raster',href:record.url,metadata:{kind:'direct-raster',href:record.url,datasetPreset:proof}}};}
test('corrected WRB display ranges remain bound to original class or unconverted raw-score files',()=>{for(const record of records.originals){const {dataset,asset}=source(record);const range=nextDirectRange(dataset,asset);assert.ok(range);assert.equal(range[0],0);if(record.layer==='most-probable')assert.equal(range[1],29);else assert.ok(range[1]>=record.maximum);assert.equal(asset.metadata.datasetPreset.layer.nodata,255);assert.equal(records.classLegend[0].name,'Acrisols');}}
);
test('wrong SoilGrids release, depth/date selectors and inferred probability calibration cannot activate a reviewed display profile',()=>{for(const mutate of [s=>s.dataset.version='SoilGrids 2.0',s=>s.asset.metadata.datasetPreset.request.year=2025,s=>s.asset.metadata.datasetPreset.layer.scale=0.01,s=>s.asset.metadata.datasetPreset.layer.nodata=0,s=>s.asset.metadata.datasetPreset.layer.unit='percent',s=>s.asset.href+='?other']){const s=source(records.originals[0]);mutate(s);assert.equal(nextDirectRange(s.dataset,s.asset),undefined);}});
